  for (ConversionPatternToken token : event.getConversionPattern().getTokens()) {
    switch (token.getType()) {
      case LITERAL:
        // Output the literal text
        output.append(token.getLiteral());
        break;
      case DATE:
        // Format the date and append it to the output
        output.append(new SimpleDateFormat(token.getDatePattern()).format(event.getTimeStamp()));
        break;
      case LOGGER:
        // Append the logger name to the output
        output.append(event.getLoggerName());
        break;
      case SEVERITY:
        // Append the severity level to the output
        output.append(event.getLevel().toString());
        break;
      case MESSAGE:
        // Append the log message to the output
        output.append(event.getMessage());
        break;
      case EXCEPTION:
        // Append the exception and stack trace to the output
        output.append(event.getThrowableStrRep());
        break;
    }
  }

  // Return the final output string
  return output.toString();
}

