public void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Invalid descriptor");
    }

    String[] typeTokens = descriptor.split(";");
    for (String typeToken : typeTokens) {
        Type type = Type.getType(typeToken);
        if (type == null) {
            throw new IllegalArgumentException("Invalid type token: " + typeToken);
        }

        switch (type.getSort()) {
            case Type.BOOLEAN:
                booleanValue = stack.popBoolean();
                break;
            case Type.CHAR:
                charValue = stack.popChar();
                break;
            case Type.BYTE:
                byteValue = stack.popByte();
                break;
            case Type.SHORT:
                shortValue = stack.popShort();
                break;
            case Type.INT:
                intValue = stack.popInt();
                break;
            case Type.LONG:
                longValue = stack.popLong();
                break;
            case Type.FLOAT:
                floatValue = stack.popFloat();
                break;
            case Type.DOUBLE:
                doubleValue = stack.popDouble();
                break;
            case Type.ARRAY:
                Object array = stack.pop();
                if (!(array instanceof Object[])) {
                    throw new IllegalArgumentException("Expected array");
                }
                popArray((Object[]) array);
                break;
            default:
                Object value = stack.pop();
                if (!(value instanceof Type)) {
                    throw new IllegalArgumentException("Expected type");
                }
                popObject((Type) value);
                break;
        }
    }
}

private void popArray(final Object[] array) {
