private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Initialize circulator
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, stop, dir);

    // Iterate through nodes on the outer face
    while (circulator.hasNext()) {
        Node currentNode = circulator.next();

        // If the node satisfies the predicate, return its circulator
        if (predicate.test(currentNode)) {
            return circulator;
        }
    }

    // If we reach the end of the outer face without finding a node that satisfies the predicate, return the stop node's circulator
    return new OuterFaceCirculator(stop, stop, dir);
}

// Inner class to represent a circulator
private class OuterFaceCirculator {
    private Node currentNode;
    private Node stopNode;
    private int direction;

    // Constructor
    public OuterFaceCirculator(Node startNode, Node stopNode, int direction) {
        currentNode = startNode;
        this.stopNode = stopNode;
        this.direction = direction;
    }

    // Returns the next node in the outer face
    public Node next() {
        // Determine the next node on the outer face
        Node nextNode = currentNode.getNeighbor(direction);

        // If the next node is the stop node, return it
        if (nextNode == stopNode) {
            return nextNode;
        }

        // If the next node is not the stop node, move the current node to the next node and return the next node
        currentNode = nextNode;
        return nextNode;
    }

    // Checks if the circulator has more nodes to iterate over
    public boolean hasNext() {
        // If the current node is not the stop node, there are more nodes to iterate over
        return currentNode != stopNode;
    }
}
