private String buildContentRange() {
    // Check if the range header is present
    if (!request.getHeaders().containsKey("Range")) {
        // No range header present, return empty string
        return "";
    }

    // Extract the range header value
    String rangeHeaderValue = request.getHeaders().get("Range").get(0);

    // Parse the range header value
    RangeHeader rangeHeader = new RangeHeader(rangeHeaderValue);

    // Check if the range is valid
    if (!rangeHeader.isValid()) {
        // Invalid range, return empty string
        return "";
    }

    // Build the content range value
    String contentRangeValue = rangeHeader.getValue();

    // Check if the content range value is present
    if (contentRangeValue == null || contentRangeValue.isEmpty()) {
        // Content range value is empty, return empty string
        return "";
    }

    // Return the content range value
    return contentRangeValue;
}
