public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // Check if the file exists and is not empty
    if (!file.exists() || file.length() == 0) {
        throw new IOException("Invalid file or empty file is provided.");
    }

    // Check if the time ranges are valid
    if (timeRanges == null || timeRanges.isEmpty()) {
        throw new IllegalArgumentException("Invalid time ranges are provided.");
    }

    // Parse the file line by line
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            // Parse the timestamp from the line
            long timestamp = Long.parseLong(line.split("\\s")[0]);
            // Check if the timestamp is in the specified time range
            for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                if (timestamp >= timeRange.getStartTime() && timestamp <= timeRange.getEndTime()) {
                    // Extract the thread ID from the line
                    int threadId = Integer.parseInt(line.split("\\s")[1]);
                    // Extract the thread name from the line
                    String threadName = line.split("\\s")[2];
                    // Create a new ThreadSnapshot instance
                    ThreadSnapshot threadSnapshot = new ThreadSnapshot(threadId, timestamp, threadName);
                    // Add the ThreadSnapshot to the list
                    threadSnapshots.add(threadSnapshot);
                    break;
                }
            }
        }
    } catch (IOException e) {
        throw new IOException("Error reading the file.", e);
    }

    return threadSnapshots;
}
